#################################################
# 検索
#################################################

def name_search_matches(text):
    # Imported here to avoid a circular import while progressData is initialized.
    from progress_profiles import normalize
    query = normalize(text)
    if not query:
        return []
    exact = [p for p in progressData if query == normalize(p['progressName'])]
    nickname = [p for p in progressData if any(query == normalize(p.get(f'progressNickname{i}', '')) for i in range(1, 4))]
    partial = [p for p in progressData if query in normalize(p['progressName'])]
    nickname_partial = [p for p in progressData if any(query in normalize(p.get(f'progressNickname{i}', '')) for i in range(1, 4))]
    return exact or nickname or partial or nickname_partial


def progressSearch(text):
    text = text.strip()
    if not text:
        return response(3)
    found = name_search_matches(text)
    if not found:
        # Keep existing keyword searches, but prefer name matches over profile text.
        found = [p for p in progressData if any(text in p.get(key, '') for key in
                 ('progressWorld', 'progressLike', 'progressDisLike', 'progressInscription',
                  'progressDetail1', 'progressDetail2', 'progressDetail3', 'progressEx'))]
    result = ''

    if len(found) == 0:
        return response(3)

    elif len(found) == 1:

        p = found[0]

        result += f"【名前】{p['progressName']}\n"

        if p["progressWorld"]:
            result += f"【世界】{p['progressWorld']}\n"

        if p["progressLike"]:
            result += f"【好きなもの】{p['progressLike']}\n"

        if p["progressDisLike"]:
            result += f"【嫌いなもの】{p['progressDisLike']}\n"

        if p["progressInscription"]:
            result += f"【座右の名】{p['progressInscription']}\n"

        if p["progressDetail1"]:
            result += f"【情報】{p['progressDetail1']}\n"

        if p["progressDetail2"]:
            result += f"【情報】{p['progressDetail2']}\n"

        if p["progressDetail3"]:
            result += f"【情報】{p['progressDetail3']}\n"

        if p["progressEx"]:
            result += f"【EX】{p['progressEx']}\n"

        return result

    else:

        if len(found) > 10:
            return response(4)

        result = response(5) + "\n\n"

        for p in found:
            result += p["progressName"] + "\n"

        return result

#################################################
# 世界別一覧
#################################################

def progressSearchAll(type):

    blue = []
    black = []
    red = []
    white = []
    green = []

    for p in progressData:

        if p["progressWorld"] == "青":
            blue.append(p["progressName"])

        if p["progressWorld"] == "黒":
            black.append(p["progressName"])

        if p["progressWorld"] == "赤":
            red.append(p["progressName"])

        if p["progressWorld"] == "白":
            white.append(p["progressName"])

        if p["progressWorld"] == "緑":
            green.append(p["progressName"])

    result = response(6)

    def make(world, data):
        text = f"\n\n【{world}の世界】\n"
        for n in data:
            text += "・" + n + "\n"
        return text

    if type == 0:
        result += make("青", blue)

    elif type == 1:
        result += make("黒", black)

    elif type == 2:
        result += make("赤", red)

    elif type == 3:
        result += make("白", white)

    elif type == 4:
        result += make("緑", green)

    return result
